package com.cinenest.notifications.internal;
import com.cinenest.notifications.*;
import com.cinenest.identity.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
class NotificationService implements NotificationFacts {
 private final NotificationRepository repo;private final NotificationPolicy policy;private final ScopedAuthorization auth;private final NotificationRecipients recipients;private final List<NotificationContext> sources;
 NotificationService(NotificationRepository repo,NotificationPolicy policy,ScopedAuthorization auth,NotificationRecipients recipients,List<NotificationContext> sources){this.repo=repo;this.policy=policy;this.auth=auth;this.recipients=recipients;this.sources=sources;}
 static UUID id(Map<String,Object> r,String k){return (UUID)r.get(k);}static long number(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private NotificationContext source(Map<String,Object> r){return sources.stream().filter(s->s.source().equals(r.get("source"))).findFirst().orElseThrow(()->new NotificationFailure(503));}
 @Transactional(propagation=org.springframework.transaction.annotation.Propagation.MANDATORY)
 public void record(Fact f){if(f==null||f.event()==null||f.owner()==null||f.venue()==null||f.resource()==null||f.revision()<0||f.kind()==null||!Set.of("PAYMENTS","ACCESS","BOOKING").contains(f.source())||f.source().equals("BOOKING")!=(f.kind()==Kind.AMENDMENT_CONFIRMED)||f.source().equals("PAYMENTS")&&!f.kind().name().startsWith("BANK_")&&!f.kind().equals(Kind.SYNTHETIC_OPERATION_EXCEPTION)||f.source().equals("ACCESS")&&f.kind().name().startsWith("BANK_"))throw new NotificationFailure(400);repo.event(f);}
 private void principal(UUID a,String action,UUID venue){policy.configured();repo.lockActor(a);if(!policy.accounts().contains(a)||!(venue==null?auth.permitsSelf(a,action,true):auth.permits(a,venue,action,true)))throw new NotificationFailure(403);if(repo.rate(a,policy.positive("rate-seconds"))>=policy.positive("rate-count"))throw new NotificationFailure(429);}
 private boolean current(Map<String,Object> r){return source(r).current(id(r,"resource_id"),number(r,"source_revision"));}
 private boolean recipient(Map<String,Object> r,UUID actor){return actor.equals(r.get("recipient_id"))&&policy.accounts().contains(actor)&&auth.permitsSelf(actor,"notification.read",false)&&(!r.get("audience").equals("STAFF")||source(r).staffMayRead(actor,id(r,"venue_id")));}
 private boolean visible(Map<String,Object> r,UUID actor){return recipient(r,actor)&&r.get("available_at")!=null&&repo.unexpired(id(r,"intent_id"))&&current(r);}
 static String message(String kind){return switch(Kind.valueOf(kind)){case AMENDMENT_CONFIRMED->"Synthetic reschedule confirmed. Open your protected booking workspace. No physical operation was performed.";case BANK_CLAIM_RECEIVED->"Synthetic bank claim received for review. A receipt is not bank credit.";case BANK_REVIEW_COMPLETED->"Synthetic receipt review completed. This does not verify bank funds.";case BANK_REVIEW_NEEDS_INFORMATION->"Synthetic review needs more information. Open your protected bank workspace.";case BANK_REVIEW_REJECTED->"Synthetic review rejected the claim. No financial conclusion is implied.";case SYNTHETIC_ACCESS_READY->"Matching simulator installation recorded. No physical door access or credential is delivered.";case SYNTHETIC_ACCESS_EXPIRED->"Synthetic credential expired. Physical access is not controlled here.";case SYNTHETIC_ACCESS_REVOKED->"Synthetic credential revoked. No physical door command was sent.";case SYNTHETIC_OPERATION_EXCEPTION->"Synthetic operation needs authorized review. Open the protected workspace.";};}
 private Map<String,Object> view(Map<String,Object> r,boolean admin){var v=new LinkedHashMap<String,Object>();for(String k:List.of("intent_id","venue_id","kind","template_version","revision","operation_id","state","attempts","expires_at","read_at"))v.put(k,r.get(k));v.put("id",r.get("intent_id"));v.put("synthetic",true);v.put("liveDelivery",false);v.put("label","SYNTHETIC NOTIFICATION TEST — NO REAL DELIVERY");if(admin){v.put("history",repo.history(id(r,"intent_id")));v.put("attemptHistory",repo.attempts(id(r,"operation_id")));}else{v.put("message",message(r.get("kind").toString()));v.put("destination",r.get("destination"));}return v;}
 @Transactional public Object inbox(UUID actor,UUID id,int page,int size){principal(actor,"notification.read",null);bounds(page,size);Object result;if(id!=null){var r=repo.row(id,false);if(!visible(r,actor))throw new NotificationFailure(404);result=view(r,false);}else{var all=repo.inbox(actor).stream().filter(r->visible(r,actor)).toList();result=Map.of("items",all.stream().skip((long)page*size).limit(size).map(r->view(r,false)).toList(),"unreadCount",all.stream().filter(r->r.get("read_at")==null).count(),"page",page,"size",size,"hasNext",(long)(page+1)*size<all.size());}repo.audit(actor,null,id,null,"INBOX_READ","ALLOW");return result;}
 @Transactional public Object admin(UUID actor,UUID venue,UUID id,int page,int size){principal(actor,"notification.admin.read",venue);bounds(page,size);Object result;if(id!=null){var r=repo.row(id,false);if(!venue.equals(r.get("venue_id")))throw new NotificationFailure(404);result=view(r,true);}else{var all=repo.queue(venue);result=Map.of("items",all.stream().skip((long)page*size).limit(size).map(r->view(r,true)).toList(),"unassigned",repo.unassigned(venue).size(),"unassignedWork",repo.unassigned(venue),"page",page,"size",size,"hasNext",(long)(page+1)*size<all.size());}repo.audit(actor,null,id,venue,"ADMIN_READ","ALLOW");return result;}
 private static void bounds(int page,int size){if(page<0||page>10000||size<1||size>50)throw new NotificationFailure(400);}
 private static UUID uuid(Object v){try{return UUID.fromString(Objects.toString(v,""));}catch(RuntimeException e){throw new NotificationFailure(400);}}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 @Transactional public Object command(UUID actor,UUID venue,UUID id,String kind,Map<String,Object> body){
  principal(actor,kind.equals("read")?"notification.mark-read":"notification.admin."+kind,venue);var allowed=new HashSet<>(List.of("commandKey","expectedRevision"));if(kind.equals("simulations"))allowed.add("fixture");if(!allowed.containsAll(body.keySet())||!body.keySet().containsAll(List.of("commandKey","expectedRevision")))throw new NotificationFailure(400);
  Object expected=body.get("expectedRevision");if(!(expected instanceof Number n)||n.longValue()<0||n.doubleValue()!=n.longValue())throw new NotificationFailure(400);UUID key=uuid(body.get("commandKey"));var r=repo.row(id,true);if(venue==null?!visible(r,actor):!venue.equals(r.get("venue_id")))throw new NotificationFailure(404);
  String digest=hash(kind+":"+id+":"+venue+":"+new TreeMap<>(body));var prior=repo.command(actor,key);if(!prior.isEmpty()){if(!digest.equals(prior.get("payload_hash")))throw new NotificationFailure(409);return view(r,venue!=null);}if(n.longValue()!=number(r,"revision"))throw new NotificationFailure(409);
  if(!kind.equals("read")&&(!repo.unexpired(id)||!current(r)))throw new NotificationFailure(409);
  switch(kind){case "read"->repo.read(id);case "retries"->{if(!r.get("state").equals("DELIVERY_FAILED"))throw new NotificationFailure(409);if(number(r,"attempts")>=policy.positive("attempt-limit"))throw new NotificationFailure(429);repo.retry(id,policy.positive("retry-seconds"));}case "reconciliations"->{if(!r.get("state").equals("DELIVERY_UNKNOWN"))throw new NotificationFailure(409);repo.reconcile(id);}case "simulations"->{if(!r.get("state").equals("READY"))throw new NotificationFailure(409);String fixture=Objects.toString(body.get("fixture"),"");if(!Set.of("ACCEPTED","FAILED","UNKNOWN_ACCEPTED","UNKNOWN_FAILED").contains(fixture))throw new NotificationFailure(400);repo.fixture(id,fixture);}default->throw new NotificationFailure(400);}
  repo.command(actor,key,id,kind,digest);repo.audit(actor,id(r,"event_id"),id,venue,kind,kind.equals("read")?"USER_MARKED_READ":"SYNTHETIC_CONTROL");return view(repo.row(id,false),venue!=null);
 }
 @Transactional public void resolve(){policy.configured();for(var e:repo.unresolved()){
  UUID event=id(e,"event_id"),owner=id(e,"owner_id"),venue=id(e,"venue_id");if(!current(e)){repo.resolved(event);continue;}
  boolean ownerResolved=policy.accounts().contains(owner)&&auth.permitsSelf(owner,"notification.read",false);if(ownerResolved)repo.intent(event,owner,false,policy.positive("expiry-seconds"),policy.positive("retention-seconds"));
  boolean staffResolved=!Boolean.TRUE.equals(e.get("reviewers"));if(!staffResolved)for(UUID staff:recipients.bankReviewers(venue))if(!staff.equals(owner)&&policy.accounts().contains(staff)&&auth.permitsSelf(staff,"notification.read",false)&&source(e).staffMayRead(staff,venue)){repo.intent(event,staff,true,policy.positive("expiry-seconds"),policy.positive("retention-seconds"));staffResolved=true;}
  if(ownerResolved&&staffResolved)repo.resolved(event);
 }}
 @Transactional public Map<String,Object> claim(UUID operation){policy.configured();var r=repo.claim(operation,policy.positive("lease-seconds"),policy.positive("attempt-limit"));if(!r.isEmpty()&&(!visibleForDispatch(r)||!current(r))){repo.suppress(id(r,"intent_id"));return Map.of();}return r;}
 private boolean visibleForDispatch(Map<String,Object> r){return recipient(r,id(r,"recipient_id"))&&repo.unexpired(id(r,"intent_id"));}
 @Transactional public void finish(Map<String,Object> claimed,String outcome,String evidence){var r=repo.row(id(claimed,"intent_id"),true);if(!visibleForDispatch(r)||!current(r)){repo.suppress(id(r,"intent_id"));return;}if(repo.finish(id(r,"operation_id"),number(claimed,"fence"),outcome,evidence))repo.audit(null,id(r,"event_id"),id(r,"intent_id"),id(r,"venue_id"),"LOCAL_CAPTURE",outcome);}
}
